import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.security.MessageDigest;
import java.sql.*;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.*;

public class BankBatchJob {

    private static final Charset UTF8 = Charset.forName("UTF-8");
    private static final RoundingMode HALF_EVEN = RoundingMode.HALF_EVEN;

    private static final File DATA_DIR = new File("/app/data");
    private static final File OUT_DIR = new File("/app/output");

    // Must be a single literal string containing MODE=DB2 and /app/output/bankdb
    private static final String JDBC_URL = "jdbc:h2:/app/output/bankdb;MODE=DB2";

    public static void main(String[] args) throws Exception {
        ensureCleanOutputDir();

        String bizDate = readFirstLine(new File(DATA_DIR, "biz_date.txt")).trim();
        int bizDay = parseDay(bizDate);

        Map<String, FeeRule> feeRules = loadFeeRules(new File(DATA_DIR, "fee_rules.csv"));
        List<String> pivots = loadPivots(new File(DATA_DIR, "fx_pivots.csv"));
        FxBook fxBook = loadFxRates(new File(DATA_DIR, "fx_rates.csv"));

        LinkedHashMap<String, Account> accounts = loadAccounts(new File(DATA_DIR, "accounts.csv"));

        List<Txn> txns = loadTxns(new File(DATA_DIR, "transactions.csv"));

        // Precompute reversal relationships: if reversal_of points to any tx_id in file -> both rows REVERSED
        HashSet<String> allTxIds = new HashSet<String>();
        for (Txn t : txns) allTxIds.add(t.txId);
        HashSet<String> reversedTxIds = new HashSet<String>();
        for (Txn t : txns) {
            if (t.reversalOf != null && t.reversalOf.length() > 0 && allTxIds.contains(t.reversalOf)) {
                reversedTxIds.add(t.txId);
                reversedTxIds.add(t.reversalOf);
            }
        }

        // H2 DB: create and load ACCOUNTS + TXNS (all rows)
        createAndLoadDb(accounts, txns, bizDate);

        // Process txns into exceptions + per-account adjustments
        LinkedHashMap<String, BigDecimal> acctAdjSum = new LinkedHashMap<String, BigDecimal>();
        for (String acctId : accounts.keySet()) {
            acctAdjSum.put(acctId, bd("0.00"));
        }

        List<ExceptionRow> exceptions = new ArrayList<ExceptionRow>();
        int validTxs = 0;
        int skippedTxs = 0;

        HashSet<String> seenTxIds = new HashSet<String>();

        for (Txn t : txns) {
            boolean isDup = seenTxIds.contains(t.txId);
            if (!isDup) seenTxIds.add(t.txId);

            String reason = null;

            // Reasons in required precedence order
            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !allTxIds.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else {
                Account acct = accounts.get(t.accountId);
                if (acct == null) {
                    // Not specified in the required list; treat as a skipped record with an explicit reason.
                    reason = "ACCOUNT_MISSING";
                } else {
                    BigDecimal fx = null;
                    if (!t.currency.equals(acct.currency)) {
                        fx = fxBook.resolveRate(t.currency, acct.currency, t.effectiveDay, pivots);
                        if (fx == null) {
                            reason = "FX_MISSING";
                        }
                    }

                    if (reason == null) {
                        if (t.effectiveDay > bizDay) {
                            reason = "AFTER_BIZ_DATE";
                        }
                    }

                    if (reason == null) {
                        if (!"POSTED".equals(t.status)) {
                            reason = t.status;
                        }
                    }

                    if (reason == null) {
                        if (isDup) {
                            reason = "DUPLICATE";
                        }
                    }

                    if (reason == null) {
                        // Valid: convert to account ccy, then fee, then add adjusted amount
                        BigDecimal amtAcc = t.amount;
                        if (fx != null) {
                            amtAcc = amtAcc.multiply(fx).setScale(10, HALF_EVEN).setScale(2, HALF_EVEN);
                        } else {
                            amtAcc = amtAcc.setScale(2, HALF_EVEN);
                        }

                        FeeRule rule = feeRules.get(acct.feePlan);
                        BigDecimal adjusted = applyFee(rule, amtAcc);

                        BigDecimal cur = acctAdjSum.get(acct.accountId);
                        if (cur == null) cur = bd("0.00");
                        acctAdjSum.put(acct.accountId, cur.add(adjusted).setScale(2, HALF_EVEN));
                        validTxs++;
                    }
                }
            }

            if (reason != null) {
                exceptions.add(new ExceptionRow(t.rowNum, t.txId, reason));
                skippedTxs++;
            }
        }

        // Build interest.csv bytes (to compute md5 from the exact bytes written)
        InterestAndTotals it = buildInterestCsv(accounts, acctAdjSum, bizDate, bizDay);

        // Write interest.csv (LF + trailing newline)
        writeBytes(new File(OUT_DIR, "interest.csv"), it.interestCsvBytes);

        String reportMd5 = md5Hex(it.interestCsvBytes);

        // Write exceptions.csv (LF + trailing newline)
        writeExceptionsCsv(new File(OUT_DIR, "exceptions.csv"), exceptions);

        // Write stats.json (single line, no newline)
        writeStatsJson(new File(OUT_DIR, "stats.json"), bizDate, accounts.size(), validTxs, skippedTxs, it.totalInterest2dp, reportMd5);

        // Insert RUN_AUDIT row
        insertRunAudit(bizDate, accounts.size(), validTxs, skippedTxs, reportMd5);
    }

    private static void ensureCleanOutputDir() throws IOException {
        if (!OUT_DIR.exists()) {
            if (!OUT_DIR.mkdirs()) throw new IOException("Failed to create /app/output");
        }
        // Clear known output files to keep reruns deterministic
        deleteIfExists(new File(OUT_DIR, "interest.csv"));
        deleteIfExists(new File(OUT_DIR, "exceptions.csv"));
        deleteIfExists(new File(OUT_DIR, "stats.json"));
        deleteIfExists(new File(OUT_DIR, "bankdb.h2.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.lock.db"));
    }

    private static void deleteIfExists(File f) {
        try {
            if (f.exists()) f.delete();
        } catch (Exception ignored) {
        }
    }

    private static LinkedHashMap<String, Account> loadAccounts(File f) throws IOException {
        LinkedHashMap<String, Account> out = new LinkedHashMap<String, Account>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("accounts.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                Account acct = new Account();
                acct.accountId = a[0];
                acct.openedAt = a[1];
                acct.openedDay = parseDay(acct.openedAt);
                acct.startBalance = bd(a[2]).setScale(2, HALF_EVEN);
                acct.baseApr = bd(a[3]);
                acct.promoApr = bd(a[4]);
                acct.promoDays = Integer.parseInt(a[5]);
                acct.tierThreshold = bd(a[6]).setScale(2, HALF_EVEN);
                acct.tierApr = bd(a[7]);
                acct.currency = a[8];
                acct.feePlan = a[9];
                out.put(acct.accountId, acct);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static List<Txn> loadTxns(File f) throws IOException {
        ArrayList<Txn> out = new ArrayList<Txn>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("transactions.csv missing header");
            String line;
            int rowNum = 0;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                rowNum++;
                String[] a = splitCsv(line);
                Txn t = new Txn();
                t.rowNum = rowNum;
                t.txId = a[0];
                t.accountId = a[1];
                t.effectiveDate = a[2];
                t.effectiveDay = parseDay(t.effectiveDate);
                t.amount = bd(a[3]).setScale(2, HALF_EVEN);
                t.currency = a[4];
                t.status = a[5];
                t.reversalOf = (a.length >= 7) ? a[6] : "";
                if (t.reversalOf == null) t.reversalOf = "";
                out.add(t);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static Map<String, FeeRule> loadFeeRules(File f) throws IOException {
        HashMap<String, FeeRule> out = new HashMap<String, FeeRule>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fee_rules.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                FeeRule r = new FeeRule();
                r.feePlan = a[0];
                r.appliesTo = a[1];
                r.flatFee = bd(a[2]).setScale(2, HALF_EVEN);
                r.pctFee = bd(a[3]);
                r.minFee = bd(a[4]).setScale(2, HALF_EVEN);
                r.maxFee = bd(a[5]).setScale(2, HALF_EVEN);
                out.put(r.feePlan, r);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static List<String> loadPivots(File f) throws IOException {
        ArrayList<String> out = new ArrayList<String>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fx_pivots.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                out.add(a[0]);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static FxBook loadFxRates(File f) throws IOException {
        FxBook book = new FxBook();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fx_rates.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                int rateDay = parseDay(a[0]);
                String from = a[1];
                String to = a[2];
                BigDecimal rate = bd(a[3]);
                book.add(rateDay, from, to, rate);
            }
        } finally {
            br.close();
        }
        return book;
    }

    private static BigDecimal applyFee(FeeRule rule, BigDecimal amtAcc) {
        if (rule == null) return amtAcc.setScale(2, HALF_EVEN);

        boolean isDebit = amtAcc.compareTo(BigDecimal.ZERO) < 0;
        boolean isCredit = amtAcc.compareTo(BigDecimal.ZERO) > 0;
        boolean applies;

        if ("ALL".equals(rule.appliesTo)) {
            applies = true;
        } else if ("DEBIT".equals(rule.appliesTo)) {
            applies = isDebit;
        } else if ("CREDIT".equals(rule.appliesTo)) {
            applies = isCredit;
        } else {
            applies = false;
        }

        if (!applies) {
            return amtAcc.setScale(2, HALF_EVEN);
        }

        BigDecimal abs = amtAcc.abs();
        BigDecimal feeRaw = rule.flatFee.add(rule.pctFee.multiply(abs));
        BigDecimal fee = feeRaw.setScale(2, HALF_EVEN);
        if (fee.compareTo(rule.minFee) < 0) fee = rule.minFee;
        if (fee.compareTo(rule.maxFee) > 0) fee = rule.maxFee;

        BigDecimal adjusted = amtAcc.subtract(fee);
        return adjusted.setScale(2, HALF_EVEN);
    }

    private static InterestAndTotals buildInterestCsv(LinkedHashMap<String, Account> accounts,
                                                     Map<String, BigDecimal> acctAdjSum,
                                                     String bizDate,
                                                     int bizDay) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        OutputStreamWriter osw = new OutputStreamWriter(baos, UTF8);
        BufferedWriter bw = new BufferedWriter(osw);

        BigDecimal totalInterestRawSum10dp = BigDecimal.ZERO.setScale(10, HALF_EVEN);

        bw.write("account_id,biz_date,eod_balance,apr,daily_interest\n");

        // Sorted by account_id
        ArrayList<String> acctIds = new ArrayList<String>(accounts.keySet());
        Collections.sort(acctIds);

        for (String acctId : acctIds) {
            Account a = accounts.get(acctId);
            BigDecimal adj = acctAdjSum.get(acctId);
            if (adj == null) adj = bd("0.00");

            BigDecimal eod = a.startBalance.add(adj).setScale(2, HALF_EVEN);

            BigDecimal apr = a.baseApr;
            if (eod.compareTo(a.tierThreshold) >= 0) {
                apr = apr.add(a.tierApr);
            }
            int daysSince = bizDay - a.openedDay;
            if (a.promoDays > 0 && daysSince < a.promoDays) {
                apr = apr.add(a.promoApr);
            }

            BigDecimal principal = eod;
            if (principal.compareTo(BigDecimal.ZERO) < 0) principal = BigDecimal.ZERO.setScale(2, HALF_EVEN);

            BigDecimal dailyInterestRaw = principal.multiply(apr).divide(bd("365"), 10, HALF_EVEN);
            BigDecimal dailyInterestCsv = dailyInterestRaw.setScale(2, HALF_EVEN);
            totalInterestRawSum10dp = totalInterestRawSum10dp.add(dailyInterestRaw).setScale(10, HALF_EVEN);

            bw.write(a.accountId);
            bw.write(",");
            bw.write(bizDate);
            bw.write(",");
            bw.write(eod.setScale(2, HALF_EVEN).toPlainString());
            bw.write(",");
            bw.write(apr.setScale(6, HALF_EVEN).toPlainString());
            bw.write(",");
            bw.write(dailyInterestCsv.toPlainString());
            bw.write("\n");
        }

        bw.flush();

        InterestAndTotals out = new InterestAndTotals();
        out.interestCsvBytes = baos.toByteArray();
        out.totalInterest2dp = totalInterestRawSum10dp.setScale(2, HALF_EVEN);
        return out;
    }

