        HashSet<String> allTxIds = new HashSet<String>();
        for (Txn t : txns) allTxIds.add(t.txId);
        HashSet<String> reversedTxIds = new HashSet<String>();
        for (Txn t : txns) {
            if (t.reversalOf != null && t.reversalOf.length() > 0 && allTxIds.contains(t.reversalOf)) {
