            boolean isDup = seenTxIds.contains(t.txId);
            if (!isDup) seenTxIds.add(t.txId);

            String reason = null;

            // Reasons in required precedence order
            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !allTxIds.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else {
                Account acct = accounts.get(t.accountId);
                if (acct == null) {
                    // Not specified in the required list; still record a skip reason
                    reason = "ACCOUNT_MISSING";
                } else {
                    BigDecimal fx = null;
                    if (!t.currency.equals(acct.currency)) {
